      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10월 3주~11월 2주(~11/13) 노무제공자 구직급여 제도 관련 1:1 심층면접 -남성\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.13. 18:57\n조회 23\n구독\n10월 3주~11월 2주(~11/13) 노무제공자 구직급여 제도 관련 1:1 심층면접\n노무제공자 구직급여 제도’ 조사로,\n노무제공자의 구직급여 수급 경험과 애로사항 등을 파악하고자 합니다.\n1. 인터뷰 개요\n• 일정: 10월 3주~11월 2주(~11/13) 中 하루 (*협의 예정)\n• 소요 시간: 1시간 내외\n• 방법: 대면 1:1 인터뷰\n• 사례비: 15만 원\n2. 모집 대상 및 인원\n• 정보통신 소프트웨어 기술자 2명\n• 방문판매원 2명\n• 배달라이더 2명\n• 택배기사 2명\n• 건설기계조종사 2명\n• 기타 2명 (여러 일자리를 병행하거나, 월 소득 80만원 미만 경험이 있는 자)\n3. 모집 필수조건\n• 최근 2년 내 해당 직종 종사자 (*주업/부업 포함)\n• 경력 최소 1년 이상\n• 고용보험 가입 이력이 있는 분\n아래와 같은 스크리닝 문항으로 대상자 확인/신청 부탁드립니다.\n(사전 스크리닝 문항)\n1. 해당 직종 종사 기간은 얼마나 되십니까? (① 1년 미만 /② 1년 이상~2년 미만 /③ 2년 이상~3년 미만 /④ 3년 이상)\n2. 최근 24개월 내 고용보험 가입 이력이 있습니까? (① 있음 /② 없음 /③ 모름)\n3. 구직급여 수급 경험이 있습니까? (① 있음 /② 없음 /③ 모름)\n4. 최근 2년 내 월 소득이 80만 원 미만이었던 달이 있습니까? (① 있음 /② 없음)\n5. 현재 해당 직종은 주업입니까, 부업입니까? (① 주업 /② 부업)\nhttps://forms.gle/v7nHa7mHSEnBVSay7\n10월 3주~11월 2주(~11/13) 노무제공자 구직급여 제도 관련 1:1 심층면접\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n10월 3주~11월 2주(~11/13) 노무제공자 구직급여 제도 관련 1:1 심층면접 -여성\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n10월 3주~11월 2주(~11/13) 노무제공자 구직급여 제도 관련 1:1 심층면접 -남성\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n10/16~19) 탄산음료관련 설문조사:만30-49세 여성\n좌담회알바좌담회카페\n26.10.13.\n댓글\n1\n10/16~19) 탄산음료관련 설문조사:만30-49세 남성\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
