      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n10/19) 40~69세 남녀) 최근 1년 이내 KB라이프생명에 보험금 청구하신 분 대상 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.13. 19:15\n조회 19\n구독\n10/19) 40~69세 남녀) 최근 1년 이내 KB라이프생명에 보험금 청구하신 분 대상 좌담회\n신청하신분은 재신청 안하셔도 됩니다\n- 대상 : 서울/경기/인천 거주하는 만 40~69세 남녀\n- 일정 : 2026년 10월 19일(월)/시간은 추후 안내드립니다\n- 장소 : 방배역 인근\n- 사례비 : 50,000원\n- 소요시간: 2시간 정도\n** 증빙요청: 보험금 청구 후 받으신 안내(문자, 알림톡, 우편 등) 캡처 또는 사본\n** 반드시 '엠브레인 최종 확정 카톡'을 받으셔야 선정됩니다.\n* 신청방법\n※ 이름/ 생년월일/ 성별/ 연락처 작성 후 아래 질문에 응답해주세요\n질문1) 구체적인 직업/직무(자영업,직장인,프리랜서,파트타이머(업종)/학생(학교명/학과/학년)/전업주부/무직 등)을 기재해주세요.\n질문2) 본인 혹은 본인 가족 중 해당 업종에서 근무하시는 분이 있다면 모두 선택해주세요.\n1. 광고 대행사 및 시장조사 관련 업종\n2. 컨설팅 관련 업종\n3. 보험사, 보험대리점(GA), 보험 설계사 등 보험 관련 업종\n4. 손해사정 관련 업종\n5. 해당 없음\n질문3) 현재 본인 명의로 가입하여 유지 중인 생명보험사를 기재해주세요. (ex: OO생명, OO라이프)\n질문4) 1년 이내 보험금을 청구한 보험사 및 청구시기를 기재해주세요. (본인 보험을 청구한 경우 및 가족의 보험을 본인이 직접 청구하고 안내 받은 경우 모두 포함)\n질문5) 해당 청구 건은 어떻게 처리되었습니까?\n1. 청구한 보험금이 별도 요청 없이 지급되었다\n2. 추가 서류(보완) 요청을 받은 후 지급되었다\n3. 추가 서류(보완) 요청을 받고 현재 진행 중이다\n4. 청구 금액 중 일부만 지급되었다\n5. 보험금이 지급되지 않았다(부지급)\n질문6) 보험금 청구 후 보험사로부터 받은 안내(접수, 지급, 추가 서류 요청 등)는 누가 받아서 확인하셨습니까?\n1. 본인이 직접 받아서 내용을 확인했다\n2. 본인이 받았지만 내용은 자세히 보지 않았다\n3. 설계사나 가족이 대신 받아서 전달해 주었다\n질문7) 현재 거주지 (OO시OO구)\nhttps://forms.gle/RjtYGZMaXAT98zjN8\n좋아요\n0\n송파구에서 핫한 진짜 동네 이야기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n10/15) 만 30-49세 남성) 자동차 관련 미스터리 쇼퍼 모집\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n10/19) 40~69세 남녀) 최근 1년 이내 KB라이프생명에 보험금 청구하신 분 대상 좌담회\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n10/27~29) 만 18-59세 대학(원)생, 직장인, 프리랜서, 파트타이머 여성 )스마트폰 설문조사\n좌담회알바좌담회카페\n26.10.13.\n댓글\n1\n10/27~29) 만 18-59세 대학(원)생, 직장인, 프리랜서, 파트타이머 여성)스마트폰 설문조사\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820"