      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10/15) 만 30-49세 여성) 자동차 관련 미스터리 쇼퍼 모집\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.13. 19:20\n조회 93\n구독\n10/15) 만 30-49세 남녀) 자동차 관련 미스터리 쇼퍼 모집\nl 대상 : 만 30-49세 남녀 중 국산/외산 차량 보유자로 차량 구매 상담 및 시승 경험자.\nl 서울 강남 지역 전시장에 방문이 가능한 분\n*자동차 미스테리 쇼퍼 경험자 우대\nl OT일정 및 장소 : 10월 15일(목) 저녁 7시 (서울 충정로역)\nl 조사 방법 : OT참석 후, 조사 기간중에 본인차를 직접 몰고 전시장 방문 상담(&시승) 후 서비스 평가 체크리스트 작성, 녹취파일 제출 필수\nl 조사 일정 : 10월중순~11월초 사이에 전시장 방문 (주중 또는 주말)\nl 진행 소요 예상 시간 : 전시장마다 약 1시간반 내외 (현장 상황에 따라 다를 수 있음)\nl 사례비 (1개 전시장 비용)\n① 서울 강남 지역 : 7만원 + OT 참석비(2만원)\nl 사례비 지급 방법 : 전체 조사가 종료되는 시점에 계좌로 입금.\nl 신청 방법 (필수 기입 내용)\n1) 이름/성별/생년월일/만나이/거주구/연락처/직업/월가구소득/이메일주소\n2) 결혼여부 및 자녀여부(자녀있는분은 자녀나이)\n3) 본인 주 운전 차량모델명/연식\n4) 자동차 미스테리쇼퍼 경험 여부 (경험자는 참여 브랜드 기입)\n5) 방문 가능한 일정(주중or주말)\n보다 자세한 내용은 유선 통화 시 설명 드리겠습니다. 차량 상담을 진심으로 즐기고 좋아하시면서 책임감 있게 참여해주실 분만 신청해 주세요.\nhttps://forms.gle/EAJXpidGz5KcZrVa8\n10/15) 만 30-49세 남녀) 자동차 관련 미스터리 쇼퍼 모집\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구 이웃끼리 공유하는 동네 꿀정보\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n10/19~23)만 18세 이상 성인남성 )임상시험 참여 경험이 있는 분 온라인 1:1 인터뷰 조사\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n10/15) 만 30-49세 여성) 자동차 관련 미스터리 쇼퍼 모집\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n10/15) 만 30-49세 남성) 자동차 관련 미스터리 쇼퍼 모집\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n10/19) 40~69세 남녀) 최근 1년 이내 KB라이프생명에 보험금 청구하신 분 대상 좌담회\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
