      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10/19~23)만 18세 이상 성인남성 )임상시험 참여 경험이 있는 분 온라인 1:1 인터뷰 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.13. 20:47\n조회 54\n구독\n10/19~23)만 18세 이상 성인 )임상시험 참여 경험이 있는 분 온라인 1:1 인터뷰 조사\n대상자 조건 :\n* 본인이나 가족 중 제약회사/의료 기기 회사/시장조사/의료기관에 근무하는 분 없어야 함\n* 만 18세 이상 성인\n* 만성 대사질환/종양학/신경학/면역학 질환과 관련한 임상시험의 일환으로 치료, 의약품 또는 기타 의료 중재를 제공받는 임상시험에 참여하신 적이 있어야 함\n* 임상시험 기간 동안, 다음 중 직접 경험하신 것이 1개 이상 있어야 함\n(1) 임상시험으로 인해 발생한 비용을 환급 받음\n(2) 비용을 환급 받기 위해 영수증 또는 경비 내역을 제출함\n(3) 임상시험 참여와 관련하여 지급금을 수령함\n(4) 교통편을 제공받거나 교통비를 지원받음\n(5) 숙소를 제공받거나 숙박비를 지원받음\n(6) 임상시험 참여와 관련하여 기타 실질적 또는 재정적 지원을 받음\n* 지원 절차에 직접 관여하셨거나 그 절차가 어떻게 진행되는지 알고 있어야 함(예로, 경비 청구 방법, 지급금 수령 방법, 교통편 마련 절차 등)\n조사 방법 및 소요시간 : 온라인 1:1 인터뷰, 60분소요\n일정 : 10월 19일~23일중 하루 /시간은 추후 안내드립니다\n답례비 : 5만원~7만원\n▷아래 질문에 응답해주세요 (가로로 쭉 작성해주세요)\n이름 / 전화번호 / 성별 / 나이(생년월일) / 거주지 (OO구 OO동) / 직업 / 임상시험 참여한 질환 및 약물명 / 임상시험 참여 시기\nhttps://forms.gle/pM4NXh565iNQbL137\n10/19~23)만 18세 이상 성인 )임상시험 참여 경험이 있는 분 온라인 1:1 인터뷰 조사\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n10/19~23)만 18세 이상 성인여성 )임상시험 참여 경험이 있는 분 온라인 1:1 인터뷰 조사\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n10/19~23)만 18세 이상 성인남성 )임상시험 참여 경험이 있는 분 온라인 1:1 인터뷰 조사\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n10/15) 만 30-49세 여성) 자동차 관련 미스터리 쇼퍼 모집\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n10/15) 만 30-49세 남성) 자동차 관련 미스터리 쇼퍼 모집\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
