      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크) 만40~49세 수도권 거주 남녀) AI 사용자 대상 좌담회 및 모바일 다이어리( 10월 22일부터 11월 2일 사이 7일간)\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.13. 22:25\n조회 37\n구독\n고유링크) 만40~49세 수도권 거주 남녀) AI 사용자 대상 좌담회 및 모바일 다이어리( 10월 22일부터 11월 2일 사이 7일간)\n고유링크) 만19~69세 수도권 거주 남녀) AI 사용자 대상 좌담회 및 모바일 다이어리( 10월 22일부터 11월 2일 사이 7일간)\n모집이 마감되면 링크가 열리지 않으니 참고 부탁드립니다 ~\n참여조건\n조사 대상: 1) 최근 3개월 동안 주 1회 이상 생성형 AI 서비스를 적극적으로 평소 생활에 활용하는 만 19~69세 수도권 거주 남녀\n2) 대면 좌담회, 모바일 다이어리(7일 간 진행), 홈비짓, 사후 설문조사까지 모든 조사 과정에 참여 가능한 분\n본 조사는 10월 중 대면 좌담회에 참여하고, 10월 22일부터 11월 2일 사이 7일간 다이어리를 작성하는 조사입니다.\n이후 일부 참석자분들을 선정하여 11월 11일~15일 중 학교/업무/가사/외부 취미활동 등 일상의 일부 구간에서 연구자의 동행 및 관찰을 진행하는 홈비짓(2시간 소요, 추가 사례비 지급 예정) 조사 참석을 부탁드릴 예정입니다.\n신청해주신 내용을 토대로 순차적으로 전화드릴 예정입니다.\n저희 직원과 통화 후 최종 선정 절차를 거쳐 참석 확정 되신분에 한해 조사 참여가 가능한 점 참고 부탁드립니다.\n조사장소 강남구 논현동 한국리서치 본사 (9호선:언주역)\n조사기간 2026-10-21 ~ 2026-12-31\n소요시간 2시간30분\n사례비 200,000원\n조사방법 대면 좌담회+모바일 다이어리+홈비짓(선정 시)\n안내사항 신청해주신 내용을 토대로 순차적으로 전화드릴 예정입니다. 저희 직원과의 전화 통화 및 최종 선정절차를 거쳐 참여자로 등록되신 분에 한해 조사 참여가 가능합니다.\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/807?refuser=23341&intro=2\n좋아요\n0\n'좋아요'로 마음을 나누세요!\n송파구의 더 많은 인기글 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n고유링크) 만60~69세 수도권 거주 남녀) AI 사용자 대상 좌담회 및 모바일 다이어리( 10월 22일부터 11월 2일 사이 7일간)\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n고유링크) 만50~59세 수도권 거주 남녀) AI 사용자 대상 좌담회 및 모바일 다이어리( 10월 22일부터 11월 2일 사이 7일간)\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n고유링크) 만40~49세 수도권 거주 남녀) AI 사용자 대상 좌담회 및 모바일 다이어리( 10월 22일부터 11월 2일 사이 7일간)\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n고유링크) 만30~39세 수도권 거주 남녀) AI 사용자 대상 좌담회 및 모바일 다이어리( 10월 22일부터 11월 2일 사이 7일간)\n좌담회알바좌담회카페\n26.10.13.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
