      "raw_content": "[비대면] AI 서비스 활용 차량 운전자 인터뷰-테슬라 및 전기차 운전자 우대[10만원~20만원]\n​\n대상 : AI 서비스를 적극적으로 활용하는 차량 운전자\n최근 3년 이내 테슬라 모델3 또는 모델Y 신차 구입자 우대\n전기차 운전자 우선 대상\n아래 공통 조건 1번과 2번을 모두 충족하는 분\n공통 조건\n1) AI 서비스를 적극적으로 활용하는 분 (아래 보기 중 1개 이상)\n[업무] 회사가 제공한 도구 외에 개인 구독 AI를 업무에 쓰고 있다\n[학습] AI의 학습 기능(학습 모드 · Guided Learning · NotebookLM 등)으로 주 1회 이상 공부하고 있다\n[생활] AI로 장보기 · 배달 주문 · 식당 예약 · 가족 일정 · 식단 관리 중 두 가지 이상을 하고 있다\n[여행] 최근 6개월 안에 AI로 여행 일정을 짜고 항공 · 숙소를 찾거나 예약했다\n[이동] 운전 중 차량 화면 연결이나 차량 음성비서로 AI에게 말로 일을 맡긴다\n[건강] 걸음 수 · 수면 · 심박 등 건강 데이터를 AI에 연결했거나, AI 건강 상담을 주 1회 이상 이용한다\n[콘텐츠] 콘텐츠 채널을 운영하거나, AI로 음악 · 영상 · 이미지 결과물을 만들거나 플레이리스트를 관리한다\n2) 아래 보기 중 최근 3개월 이내 경험한 AI 서비스 1개 이상\n1. 질문 · 검색, 글 작성 · 요약 · 번역\n2. 문서 · 이미지 · 표 파일을 올려 분석 · 정리\n3. AI에 메일 · 캘린더 · 드라이브 등 외부 서비스를 연결해 내용을 조회 · 검색\n4. AI가 연결된 서비스에서 직접 실행 (메일 작성 · 발송, 일정 등록, 문서 저장 등)\n5. AI가 웹브라우저나 PC 화면을 직접 조작해 작업을 처리하도록 맡김\n6. 정해진 시간이나 조건에 AI가 자동으로 작업을 반복 실행하도록 설정\n7. 여러 단계로 된 작업을 한 번에 맡기고 결과만 확인\n8. 여러 AI(에이전트)에게 역할을 나눠 동시에 작업을 맡김\n9. 지침 · 프로젝트 · 맞춤형 AI(GPTs, Gem 등)를 직접 설정해 반복 사용\n10. 자동화 워크플로 · MCP 서버 · 에이전트 · 스킬을 직접 제작\n방법 : AI 봇 온라인 인터뷰 + 1:1 화상 인터뷰\n소요시간 : AI 봇 음성 인터뷰 약 30분\n진행자와 1:1 화상 인터뷰 약 2시간\n사례비 : AI 봇 인터뷰 100,000원\n1:1 화상 인터뷰 추가 100,000원\n총 최대 200,000원\n조사참여방법\n1.선정통화\n2.AI 서비스 활용 분야 화면 캡쳐 업로드 및 설명기록 (대상여부확인)\n3.AI와 진행하는 온라인 인터뷰 진행(개별링크전송.30분간(음성으로만 진행),편한 시간대 진행)\n4.진행자와 1:1 화상 온라인 인터뷰 약 2시간\n​\n신청하기",
